// Deep merge so overlapping namespace keys (e.g. `common`, `calendar`)
// accumulate instead of a shallow spread wiping out existing strings.
function deepMerge(target, ...sources) {
  const out = Array.isArray(target) ? target.slice() : { ...target };
  for (const src of sources) {
    if (!src) continue;
    for (const k of Object.keys(src)) {
      const sv = src[k];
      if (sv && typeof sv === 'object' && !Array.isArray(sv) && out[k] && typeof out[k] === 'object' && !Array.isArray(out[k])) {
        out[k] = deepMerge(out[k], sv);
      } else {
        out[k] = sv;
      }
    }
  }
  return out;
}

