    effective: 'Inkrafttreten: 1. Januar 2024.',
    h1: 'Datenschutzerklärung',
    intro: 'BrandAura („wir") respektiert Ihre Privatsphäre. Diese Richtlinie erläutert, welche Daten wir erheben und wie wir sie verwenden.',
    lead: 'Meveryx („wir", „uns" oder „unser") betreibt BrandAura, eine KI-gestützte digitale Marketingplattform. Diese Datenschutzerklärung erläutert, wie wir Ihre Informationen erheben, verwenden, offenlegen und schützen, wenn Sie unsere Website und Dienste nutzen (gemeinsam die „Dienste"). Durch die Nutzung von BrandAura stimmen Sie den hier beschriebenen Praktiken zu.',
    rightsBody: 'Sie können jederzeit über Ihre Kontoeinstellungen den Export oder die Löschung Ihrer Daten anfordern.',
    rightsTitle: 'Ihre Rechte',
    s10Body: 'Wir können diese Datenschutzerklärung von Zeit zu Zeit aktualisieren. Wesentliche Änderungen werden über die Dienste oder per E-Mail mitgeteilt. Durch die weitere Nutzung von BrandAura nach Inkrafttreten der Änderungen akzeptieren Sie die aktualisierte Richtlinie.',
    s10Title: '10. Änderungen an dieser Richtlinie',
    s11Body: 'Fragen zu dieser Datenschutzerklärung oder Ihren Daten können Sie an Meveryx unter privacy@meveryx.com richten.',
    s11Title: '11. Kontakt',
    s1Title: '1. Informationen, die wir erheben',
    s1h1Body: 'Wenn Sie sich bei BrandAura registrieren, erheben wir die von Ihnen angegebene E-Mail-Adresse sowie optionale Profilinformationen wie Name, Unternehmen, Markenpräferenzen, verbundene Social-Konten und Konfigurationseinstellungen. Diese Informationen ermöglichen es uns, Ihr Konto zu erstellen und zu schützen sowie Ihre Erfahrung zu personalisieren.',
    s1h1Title: 'Konto- und Profildaten',
    s1h2Body: 'Wir speichern die Inhalte, die Sie generieren, sowie die von Ihnen erstellten Prompts, Bilder, Texte, Zeitpläne und Analysen, damit Ihre Arbeit verfügbar ist, wenn Sie zurückkehren. Darüber hinaus erheben wir standardmäßige Nutzungstelemetrie (z. B. zur Nutzung von Funktionen und Leistungskennzahlen), um die Dienste zu verbessern.',
    s1h2Title: 'Inhalts- und Nutzungsdaten',
    s2Item1: 'die BrandAura-Plattform bereitzustellen, zu betreiben und zu warten;',
    s2Item2: 'Ihr Konto zu authentifizieren und vor Betrug oder Missbrauch zu schützen;',
    s2Item3: 'KI-Inhalte zu generieren, die Performance zu analysieren und die von Ihnen angeforderten Funktionen bereitzustellen;',
    s2Item4: 'Produktupdates, Sicherheitshinweise und Support-Antworten zu kommunizieren;',
    s2Item5: 'die Dienste zu messen, zu analysieren und zu verbessern.',
    s2Title: '2. Wie wir Ihre Informationen verwenden',
    s3Body: 'Um generative Funktionen bereitzustellen, werden die von Ihnen übermittelten Inhalts-Prompts und Anweisungen von unseren KI-Modellen und unserer Pipeline verarbeitet. Wir verarbeiten diese Prompts sicher, übertragen sie über verschlüsselte Verbindungen und verwenden sie ausschließlich, um die von Ihnen angeforderte Ausgabe zu erzeugen. Wir verwenden Ihre Prompts nicht zum Trainieren von Modellen für andere Kunden und wenden Zugriffskontrollen an, sodass nur Sie und die in Ihrem Auftrag arbeitenden Systeme Ihre Inhalte lesen können.',
    s3Title: '3. KI-Verarbeitung Ihrer Prompts',
    s4Body: 'Wir verwenden Cookies, lokalen Speicher und ähnliche Technologien, um Sie angemeldet zu halten, Ihre Präferenzen zu speichern und zu verstehen, wie die Dienste genutzt werden. Essenzielle Cookies sind für das Funktionieren der Plattform erforderlich; Analyse- und Präferenz-Cookies sind optional und können über Ihre Browsereinstellungen verwaltet werden. Sie können nicht-essenzielle Cookies deaktivieren, auch wenn einige Funktionen dann möglicherweise nicht wie vorgesehen funktionieren.',
    s4Title: '4. Cookies und Tracking-Technologien',
    s5Body: 'Wir verkaufen Ihre persönlichen Daten nicht. Wir geben Daten nur an geprüfte Dienstleister weiter (z. B. Cloud-Hosting-, Authentifizierungs- und KI-Inferenzpartner), die sie in unserem Auftrag unter vertraglichen Sicherheitsvorkehrungen verarbeiten, oder wenn dies gesetzlich vorgeschrieben ist. Alle Daten werden von Meveryx verwaltet.',
    s5Title: '5. Datenweitergabe',
    s6Body: 'Wir speichern Ihre Kontodaten, solange Ihr Konto aktiv ist, sowie für einen angemessenen Zeitraum danach, um unseren gesetzlichen Verpflichtungen nachzukommen, Streitigkeiten zu klären und unsere Vereinbarungen durchzusetzen. Sie können jederzeit die Löschung Ihrer Daten anfordern (siehe Ihre Rechte unten).',
    s6Title: '6. Datenspeicherung',
    s7Body: 'Abhängig von Ihrem Wohnort stehen Ihnen nach geltendem Recht möglicherweise die folgenden Rechte zu, einschließlich der EU-Datenschutz-Grundverordnung (GDPR) und des California Consumer Privacy Act (CCPA):',
    s7Contact: 'Um diese Rechte auszuüben, senden Sie eine E-Mail an privacy@meveryx.com. Wir überprüfen Ihre Identität und antworten innerhalb der gesetzlich vorgeschriebenen Fristen (in der Regel innerhalb von 30 Tagen).',
    s7Item1: 'Auskunft — eine Kopie der über Sie gespeicherten personenbezogenen Daten anfordern;',
    s7Item2: 'Berichtigung — unrichtige oder unvollständige Informationen korrigieren;',
    s7Item3: 'Löschung — die Löschung Ihrer personenbezogenen Daten anfordern („Recht auf Vergessenwerden");',
    s7Item4: 'Datenübertragbarkeit — Ihre Daten in einem strukturierten, maschinenlesbaren Format erhalten;',
    s7Item5: 'Einschränkung und Widerspruch — bestimmte Verarbeitungen einschränken oder ihnen widersprechen;',
    s7Item6: 'Widerspruch gegen „Verkauf" oder Weitergabe — Einwohner Kaliforniens können dem Verkauf oder der Weitergabe personenbezogener Informationen widersprechen (wir verkaufen Ihre Daten nicht);',
    s7Item7: 'Nichtdiskriminierung — wir werden Sie für die Ausübung Ihrer Rechte nicht benachteiligen.',
    s7Title: '7. Ihre Datenschutzrechte (GDPR & CCPA)',
    s8Body: 'Wir setzen branchenübliche technische und organisatorische Maßnahmen um — einschließlich Verschlüsselung während der Übertragung und im Ruhezustand, rollenbasierter Zugriffskontrollen und kontinuierlicher Überwachung —, um Ihre Informationen zu schützen. Keine Übertragungs- oder Speichermethode ist vollständig sicher, aber wir arbeiten kontinuierlich daran, Ihr Konto zu schützen.',
    s8Title: '8. Datensicherheit',
    s9Body: 'BrandAura richtet sich nicht an Personen unter 16 Jahren, und wir erheben wissentlich keine personenbezogenen Daten von Kindern. Wenn Sie glauben, dass ein Kind uns personenbezogene Informationen übermittelt hat, kontaktieren Sie uns, und wir werden diese löschen.',
    s9Title: '9. Datenschutz für Kinder',
