    s5Body: 'ہم آپ کی ذاتی معلومات فروخت نہیں کرتے۔ ہم ڈیٹا صرف تصدیق شدہ سروس فراہم کنندگان (جیسے کلاؤڈ ہوسٹنگ، تصدیق اور AI انفرنس پارٹنرز) کے ساتھ شیئر کرتے ہیں جو اسے معاہداتی تحفظات کے تحت ہماری جانب سے پروسیس کرتے ہیں، یا جب قانون کے مطابق ضروری ہو۔ تمام ڈیٹا کا انتظام Meveryx کرتا ہے۔',
    s5Title: '5. ڈیٹا شیئرنگ',
    s6Body: 'ہم آپ کے اکاؤنٹ کا ڈیٹا اس وقت تک رکھتے ہیں جب تک آپ کا اکاؤنٹ فعال ہے اور اس کے بعد ایک معقول مدت تک اپنی قانونی ذمہ داریوں کی تعمیل، تنازعات کے حل اور اپنے معاہدوں کے نفاذ کے لیے۔ آپ کسی بھی وقت اپنے ڈیٹا کی حذف کی درخواست کر سکتے ہیں (ذیل میں اپنے حقوق دیکھیں)۔',
    s6Title: '6. ڈیٹا برقرار رکھنا',
    s7Body: 'آپ کہاں رہتے ہیں اس پر منحصر ہے، آپ کو قابل اطلاق قانون کے تحت درج ذیل حقوق حاصل ہو سکتے ہیں، بشمول یورپی یونین کا جنرل ڈیٹا پروٹیکشن ریگولیشن (GDPR) اور کیلیفورنیا کا کنزیومر پرائیویسی ایکٹ (CCPA):',
    s7Contact: 'ان حقوق کے استعمال کے لیے، privacy@meveryx.com پر ای میل کریں۔ ہم آپ کی شناخت کی تصدیق کریں گے اور قانون کے مقرر کردہ مدت (عام طور پر 30 دن کے اندر) میں جواب دیں گے۔',
    s7Item1: 'رسائی — ہمارے پاس موجود آپ کے ذاتی ڈیٹا کی کاپی کی درخواست؛',
    s7Item2: 'تصحیح — غلط یا نامکمل معلومات کو درست کرنا؛',
    s7Item3: 'مٹانا — آپ کے ذاتی ڈیٹا کی حذف کی درخواست («بھلائے جانے کا حق»);',
    s7Item4: 'پورٹیبلٹی — اپنا ڈیٹا منظم، مشین سے پڑھنے کے قابل فارمیٹ میں وصول کرنا؛',
    s7Item5: 'محدودیت اور اعتراض — بعض پروسیسنگ کو محدود کرنا یا اس پر اعتراض کرنا؛',
    s7Item6: '«فروخت» یا شیئرنگ سے انکار — کیلیفورنیا کے رہائشی ذاتی معلومات کی کسی بھی فروخت یا شیئرنگ سے انکار کر سکتے ہیں (ہم آپ کا ڈیٹا فروخت نہیں کرتے);',
    s7Item7: 'امتیازی سلوک سے تحفظ — ہم آپ کے حقوق کے استعمال پر آپ کے ساتھ امتیازی سلوک نہیں کریں گے۔',
    s7Title: '7. آپ کے رازداری کے حقوق (GDPR اور CCPA)',
    s8Body: 'ہم آپ کی معلومات کی حفاظت کے لیے صنعتی معیار کے تکنیکی اور تنظیمی اقدامات نافذ کرتے ہیں — بشمول منتقلی اور آرام کے وقت خفیہ کاری، کردار پر مبنی رسائی کنٹرولز اور مسلسل نگرانی۔ منتقلی یا اسٹوریج کا کوئی طریقہ مکمل طور پر محفوظ نہیں ہے، لیکن ہم آپ کے اکاؤنٹ کی حفاظت کے لیے مسلسل کام کرتے ہیں۔',
    s8Title: '8. ڈیٹا سیکیورٹی',
    s9Body: 'BrandAura 16 سال سے کم عمر افراد کے لیے نہیں ہے، اور ہم جان بوجھ کر بچوں سے ذاتی ڈیٹا جمع نہیں کرتے۔ اگر آپ کو یقین ہے کہ کسی بچے نے ہمیں ذاتی معلومات فراہم کی ہیں تو ہم سے رابطہ کریں اور ہم اسے حذف کر دیں گے۔',
