    s1Body: 'آپ اپنے اکاؤنٹ کی اسناد کی رازداری اور اپنے اکاؤنٹ کے تحت ہونے والی تمام سرگرمیوں کو برقرار رکھنے کے ذمہ دار ہیں۔ آپ کو درست معلومات فراہم کرنی چاہئیں، اپنے رابطے کی تفصیلات تازہ رکھنی چاہئیں، اور کسی بھی غیر مجاز استعمال کے بارے میں فوری طور پر ہمیں آگاہ کرنا چاہیے۔ BrandAura استعمال کرنے کے لیے آپ کی عمر کم از کم 16 سال ہونی چاہیے۔',
