    s2Title: '2. قابل قبول استعمال',
    s3Body: 'BrandAura سافٹ ویئر، ماڈلز، ڈیزائن اور ٹریڈ مارکس Meveryx کی ملکیت ہیں۔ ان شرائط کے تحت، ہم آپ کو خدمات استعمال کرنے کا ایک محدود، غیر خصوصی اور منسوخ ہونے والا لائسنس دیتے ہیں۔ آپ کے تخلیق کردہ مواد پر آپ کے حقوق محفوظ رہتے ہیں، بشرطیکہ وہ دوسروں کے حقوق کی خلاف ورزی نہ کرے؛ تاہم، چونکہ AI آؤٹ پٹس منفرد نہیں ہو سکتیں، ہم اس بات کی ضمانت نہیں دیتے کہ تیار کردہ مواد فریق ثالث کے حقوق سے پاک ہے۔',
    s3Title: '3. دانشورانہ املاک',
