    s6Body: 'خدمات، بشمول تمام AI سے تیار کردہ متن اور تصاویر، «جیسا ہے» اور «جیسا دستیاب ہے» بغیر کسی قسم کی وارنٹی کے فراہم کی جاتی ہیں۔ ہم کسی بھی AI سے تیار کردہ متن یا تصویر کی درستگی، اصلیت یا کسی خاص مقصد کے لیے موزونیت کی ضمانت نہیں دیتے۔ آپ استعمال سے پہلے تمام آؤٹ پٹ کا جائزہ لینے اور اس کی تصدیق کرنے اور یہ یقینی بنانے کے ذمہ دار ہیں کہ آپ کا استعمال قابل اطلاق قانون اور پلیٹ فارم کی پالیسیوں کے مطابق ہے۔',
    s6Title: '6. ڈس کلیمرز',
    s7Body: 'قانون کی مکمل اجازت کی حد تک، Meveryx کسی بھی بالواسطہ، اتفاقی، خصوصی، نتیجے یا تعزیری نقصانات، یا منافع، ڈیٹا یا خیر سگالی کے نقصان کے لیے ذمہ دار نہیں ہوگا، جو آپ کے خدمات کے استعمال یا استعمال کرنے میں ناکامی سے پیدا ہوتا ہے یا اس سے متعلق ہوتا ہے — بشمول AI سے تیار کردہ مواد سے پیدا ہونے والے نقصانات۔ ہماری کل مجموعی ذمہ داری اس رقم سے تجاوز نہیں کرے گی جو آپ نے دعوے کو جنم دینے والے واقعے سے پہلے کے بارہ (12) مہینوں میں ہمیں ادا کی تھی۔',
