    s6Body: 'हम आपके खाते के सक्रिय रहने तक और अपनी कानूनी बाध्यताओं का पालन करने, विवादों को सुलझाने और अपने समझौतों को लागू करने के लिए उसके बाद उचित अवधि तक आपके खाते का डेटा बनाए रखते हैं। आप किसी भी समय अपने डेटा के विलोपन का अनुरोध कर सकते हैं (नीचे अपने अधिकार देखें)।',
