    s7Contact: 'इन अधिकारों का प्रयोग करने के लिए, privacy@meveryx.com पर ईमेल करें। हम आपकी पहचान सत्यापित करेंगे और कानून द्वारा आवश्यक समयसीमा (सामान्यतः 30 दिनों के भीतर) में प्रतिक्रिया देंगे।',
    s7Item1: 'एक्सेस — हमारे पास मौजूद आपके व्यक्तिगत डेटा की एक प्रति का अनुरोध करें;',
    s7Item2: 'सुधार — गलत या अधूरी जानकारी को सही करें;',
