    s7Item4: 'पोर्टेबिलिटी — अपना डेटा संरचित, मशीन-पठनीय प्रारूप में प्राप्त करें;',
    s7Item5: 'प्रतिबंध और आपत्ति — कुछ प्रक्रियाओं को सीमित करें या उन पर आपत्ति करें;',
    s7Item6: '"बिक्री" या साझाकरण से बाहर निकलना — कैलिफ़ोर्निया के निवासी व्यक्तिगत जानकारी की किसी भी बिक्री या साझाकरण से बाहर निकल सकते हैं (हम आपका डेटा नहीं बेचते हैं);',
    s7Item7: 'गैर-भेदभाव — हम आपके अधिकारों का प्रयोग करने के लिए आपके साथ भेदभाव नहीं करेंगे।',
