export const translations = {
  en: deepMerge(en, addEn, addEn2a, addEn2b, addEn2c, addEn3),
  es: deepMerge(es, addEs2, addEs3),
  fr: deepMerge(fr, addFr2, addFr3),
  de: deepMerge(de, addDe2, addDe3),
  ar: deepMerge(ar, addAr2, addAr3),
  ur: deepMerge(ur, addUr2, addUr3),
  hi: deepMerge(hi, addHi2, addHi3),
};

export const DEFAULT_LANGUAGE = 'en';

// Only the languages that actually have a full translation dictionary are
// selectable. Every other entry in LANGUAGES would fall back to English, so we
// hide them to guarantee 100% real translation coverage in the UI.
export const SUPPORTED_LANGUAGES = LANGUAGES.filter((l) => translations[l.code]);
